}

"use client"

import { useMemo, useState } from "react"
import { MenuSub } from "@ui-sdk/react/menu"

import { FloatingToolbarSubmenuContext } from "./floating-toolbar.constants"
import type { FloatingToolbarSubmenuProps } from "./floating-toolbar.types"

export function FloatingToolbarSubmenu({ defaultOpen = false, onOpenChange, ...props }: FloatingToolbarSubmenuProps) {
  const [open, setOpen] = useState(defaultOpen)
  const context = useMemo(() => ({ open, setOpen }), [open])

  return (
    <FloatingToolbarSubmenuContext value={context}>
      <MenuSub
        open={open}
        onOpenChange={(next, details) => {
          onOpenChange?.(next, details)
          if (!details.canceled) setOpen(next)
        }}
        {...props}
      />
    </FloatingToolbarSubmenuContext>
  )
}

import { createContext } from "react"

import type {
  FloatingToolbarContextValue,
  FloatingToolbarMenuContentContextValue,
  FloatingToolbarSubmenuState,
} from "./floating-toolbar.types"

export const FloatingToolbarContext = createContext<FloatingToolbarContextValue>({ placement: "inline" })

export const FloatingToolbarMenuContentContext = createContext<FloatingToolbarMenuContentContextValue>({ side: "top" })

export const FloatingToolbarSubmenuContext = createContext<FloatingToolbarSubmenuState | null>(null)

"use client"

import { useMemo, useRef } from "react"
import { Toolbar } from "@ui-sdk/react/toolbar"

import { cn } from "@/lib/cn"

import { FloatingToolbarContext } from "./floating-toolbar.constants"
import type { FloatingToolbarProps } from "./floating-toolbar.types"
import {
  floatingToolbarClasses,
  floatingToolbarSurfaceClasses,
  floatingToolbarWrapperClasses,
} from "./floating-toolbar.variants"
import { useScrollEdges } from "./use-scroll-edges"

export function FloatingToolbar({
  className,
  wrapperClassName,
  placement = "bottom",
  children,
  ...props
}: FloatingToolbarProps) {
  const scrollerRef = useRef<HTMLDivElement>(null)
  useScrollEdges(scrollerRef)
  const context = useMemo(() => ({ placement }), [placement])

  return (
    <FloatingToolbarContext value={context}>
      <div data-slot="floating-toolbar-wrapper" data-placement={placement} className={cn(floatingToolbarWrapperClasses[placement], wrapperClassName)}>
        <div data-slot="floating-toolbar-surface" className={cn(floatingToolbarSurfaceClasses, className)}>
          <Toolbar ref={scrollerRef} data-placement={placement} className={floatingToolbarClasses} {...props}>
            {children}
          </Toolbar>
        </div>
      </div>
    </FloatingToolbarContext>
  )
}

import type { ComponentProps, ReactNode } from "react"
import type { Menu, MenuContent, MenuItem, MenuSub, MenuSubContent, MenuSubTrigger } from "@ui-sdk/react/menu"
import type { Toolbar, ToolbarButton, ToolbarSeparator } from "@ui-sdk/react/toolbar"

/** Where the toolbar floats: pinned to the bottom or top of the viewport, or in the page flow. */
export type FloatingToolbarPlacement = "bottom" | "top" | "inline"

export type FloatingToolbarProps = Omit<ComponentProps<typeof Toolbar>, "className" | "orientation" | "children"> & {
  /** Classes for the visible pill (background, border, shadow) around the scrolling options. */
  className?: string
  children?: ReactNode
  /** Defaults to "bottom". */
  placement?: FloatingToolbarPlacement
  /** Classes for the positioning wrapper around the toolbar. */
  wrapperClassName?: string
}

export type FloatingToolbarButtonProps = Omit<ComponentProps<typeof ToolbarButton>, "className" | "children"> & {
  className?: string
  /** Accessible name of the icon-only button. */
  label: string
  /** The icon. Rendered with `aria-hidden`. */
  children: ReactNode
}

export type FloatingToolbarSeparatorProps = Omit<ComponentProps<typeof ToolbarSeparator>, "className"> & {
  className?: string
}

export type FloatingToolbarMenuProps = ComponentProps<typeof Menu>

export type FloatingToolbarMenuTriggerProps = FloatingToolbarButtonProps

export type FloatingToolbarMenuContentProps = Omit<ComponentProps<typeof MenuContent>, "className" | "side"> & {
  className?: string
  /** Side of the toolbar the panel opens on. Defaults to "top", or "bottom" for a toolbar placed at the top. */
  side?: FloatingToolbarSide
}

export type FloatingToolbarMenuItemProps = Omit<ComponentProps<typeof MenuItem>, "className" | "children"> & {
  className?: string
  children?: ReactNode
  /** Decorative icon before the text. */
  icon?: ReactNode
}

/** Uncontrolled: the back item and the menu keys open and close it. Use `onOpenChange` to observe it. */
export type FloatingToolbarSubmenuProps = Omit<ComponentProps<typeof MenuSub>, "open">

export type FloatingToolbarSubmenuTriggerProps = Omit<ComponentProps<typeof MenuSubTrigger>, "className" | "children"> & {
  className?: string
  children?: ReactNode
  /** Decorative icon before the text. */
  icon?: ReactNode
}

export type FloatingToolbarSubmenuContentProps = Omit<
  ComponentProps<typeof MenuSubContent>,
  "className" | "children" | "side" | "align" | "anchor" | "sideOffset" | "alignOffset"
> & {
  className?: string
  children?: ReactNode
  /** Heading shown under the back item; also names the group of sub-items. */
  title?: string
  /** Text of the item that closes this panel and returns to the previous one. Defaults to "Back". */
  backLabel?: string
}

export type FloatingToolbarSubmenuState = {
  open: boolean
  setOpen: (open: boolean) => void
}

export type FloatingToolbarSide = NonNullable<ComponentProps<typeof MenuContent>["side"]>

export type FloatingToolbarContextValue = {
  placement: FloatingToolbarPlacement
}

export type FloatingToolbarMenuContentContextValue = {
  side: FloatingToolbarSide
}

import { useEffect } from "react"
import type { RefObject } from "react"

/**
 * Marks a horizontal scroller with `data-more-start` / `data-more-end` while content
 * hides past that edge. Reads the scroll position on scroll, resize and content changes,
 * so it updates synchronously in every browser.
 */
export function useScrollEdges(scrollerRef: RefObject<HTMLElement | null>) {
  useEffect(() => {
    const root = scrollerRef.current
    if (!root) return

    const update = () => {
      // scrollLeft is negative in right-to-left scrollers, so measure its distance from 0.
      const fromStart = Math.abs(root.scrollLeft)
      const overflow = root.scrollWidth - root.clientWidth
      root.toggleAttribute("data-more-start", fromStart > 1)
      root.toggleAttribute("data-more-end", overflow - fromStart > 1)
    }

    update()
    root.addEventListener("scroll", update, { passive: true })
    const resize = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(update)
    resize?.observe(root)
    const mutation = typeof MutationObserver === "undefined" ? null : new MutationObserver(update)
    mutation?.observe(root, { childList: true, subtree: true })

    return () => {
      root.removeEventListener("scroll", update)
      resize?.disconnect()
      mutation?.disconnect()
    }
  }, [scrollerRef])
}
